<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyProjectDiscussionChanges.php';require_once __DIR__.'/CompanyProjectDiscussionFiles.php';
/** Finite page composition; every included projection is confirmed after the other portal readers. */
final class CompanyProjectDiscussionExtrasPage
{
    public static function get($c,array $session,int $issuer,int $project,?array $thread):array{$changes=new CompanyProjectDiscussionChanges($c->db,db_prefix(),(string)$c->config->item('encryption_key'));$files=new CompanyProjectDiscussionFiles($c->db,db_prefix(),(string)$c->config->item('encryption_key'));$state=['workspace'=>null,'change_receipt'=>null,'file_receipt'=>null,'files'=>[]];$post=$c->input->get('discussion_post',false);$parent=$c->input->get('discussion_parent',false);if(($post===null)!==($parent===null))throw new DomainException('company_project_discussion_unavailable');if($post!==null)$state['workspace']=$changes->workspace($session,$issuer,$project,$parent,$post);foreach(['discussion_change_receipt'=>'change_receipt','discussion_file_receipt'=>'file_receipt'] as $query=>$field){$key=$c->input->get($query,false);if($key!==null){if(!is_string($key))throw new DomainException('company_project_discussion_unavailable');$reader=$field==='change_receipt'?$changes:$files;$state[$field]=$reader->receipt($session,$issuer,$project,$key);}}$wanted=[];if($thread)foreach($thread['posts'] as $item)$wanted[(int)$item['id']]=(int)$thread['id'];foreach(['workspace','change_receipt','file_receipt'] as $field){$r=$state[$field];if($r&&($field!=='change_receipt'||$r['current_body']!==null))$wanted[(int)$r['post_id']]=(int)$r['discussion_id'];}foreach($wanted as $id=>$parentId)$state['files'][$id]=$files->contactList($session,$issuer,$project,$parentId,$id);return $state;}
    public static function confirm($c,array $session,int $issuer,int $project,array $state):void{$changes=new CompanyProjectDiscussionChanges($c->db,db_prefix(),(string)$c->config->item('encryption_key'));$files=new CompanyProjectDiscussionFiles($c->db,db_prefix(),(string)$c->config->item('encryption_key'));if($state['workspace'])$changes->confirmWorkspace($session,$issuer,$project,$state['workspace']);if($state['change_receipt'])$changes->confirmReceipt($session,$issuer,$project,$state['change_receipt']);if($state['file_receipt'])$files->confirmReceipt($session,$issuer,$project,$state['file_receipt']);foreach($state['files'] as $list)$files->confirmList($session,$issuer,$project,$list);}
}
